+  const results = [() => respond(503), () => { throw new TypeError('fetch failed'); }, () => respond(200, { ok: 1 })];
+  const fetch = async () => results.shift()();
+  const naps = [];
+  assert.deepEqual(await fetchJson('https://x', { fetch, sleep: async (ms) => naps.push(ms) }), { ok: 1 });
